"""Interactive chat: answers with citations and lists the pages actually retrieved."""
import uuid

from langchain_core.messages import ToolMessage

from agent import agent


def ask(question: str, thread_id: str):
    config = {"configurable": {"thread_id": thread_id}}  # the checkpointer needs thread_id
    result = agent.invoke({"messages": [{"role": "user", "content": question}]}, config)
    return result["messages"]


def retrieved_pages(messages) -> set[str]:
    """Collect [file p.N] tags from tool artifacts, newest turn only."""
    pages = set()
    for msg in reversed(messages):
        if msg.type == "human":
            break  # stop at the current user turn
        if isinstance(msg, ToolMessage) and msg.artifact:
            for d in msg.artifact:
                pages.add(f"{d.metadata['file']} p.{d.metadata['page_number']}")
    return pages


if __name__ == "__main__":
    thread_id = str(uuid.uuid4())
    print("Ask about your PDFs (blank line to quit).")
    while question := input("\nYou: ").strip():
        messages = ask(question, thread_id)
        print(f"\nAgent: {messages[-1].content}")
        pages = retrieved_pages(messages)
        print(f"Retrieved: {', '.join(sorted(pages)) if pages else 'nothing relevant'}")

