import operator
from typing import Annotated, TypedDict
from langgraph.graph import StateGraph, START, END
from langgraph.checkpoint.memory import InMemorySaver
DOCS = ["LangGraph checkpointers save state per thread.", "Reducers merge node updates."]
class State(TypedDict):
    question: str
    docs: list[str]
    attempts: Annotated[int, operator.add]
    answer: str
def retrieve(state: State):
    words = state["question"].lower().split()
    hits = [d for d in DOCS if any(w in d.lower() for w in words)]
    return {"docs": hits, "attempts": 1}
def rewrite(state: State):
    return {"question": state["question"] + " checkpointers"}
def generate(state: State):
    return {"answer": " ".join(state["docs"]) or "I don't know."}
def grade(state: State) -> str:
    return "generate" if state["docs"] or state["attempts"] >= 3 else "rewrite"
b = StateGraph(State)
b.add_node("retrieve", retrieve); b.add_node("rewrite", rewrite); b.add_node("generate", generate)
b.add_edge(START, "retrieve")
b.add_conditional_edges("retrieve", grade, ["generate", "rewrite"])
b.add_edge("rewrite", "retrieve"); b.add_edge("generate", END)
graph = b.compile(checkpointer=InMemorySaver())
cfg = {"configurable": {"thread_id": "rag-1"}}
print(graph.invoke({"question": "xyz", "attempts": 0}, cfg)["answer"])
for snap in graph.get_state_history(cfg): print(snap.next, snap.values.get("attempts"))

