from typing import Literal
from langgraph.types import Command

def grade(state: State) -> Command[Literal["retrieve", "generate"]]:
    if is_poor(state["documents"]):
        return Command(
            update={"retries": state["retries"] + 1},
            goto="retrieve",
        )
    return Command(goto="generate")

from langgraph.types import Send

def fan_out(state: State):
    return [Send("grade_one", {"doc": d, "question": state["question"]})
            for d in state["documents"]]

builder.add_conditional_edges("retrieve", fan_out, ["grade_one"])

class InputState(TypedDict):
    question: str
class OutputState(TypedDict):
    answer: str
class OverallState(InputState, OutputState):
    documents: list
    retries: int

builder = StateGraph(OverallState, input_schema=InputState, output_schema=OutputState)

def rewrite_query(state: State):
    state["retries"] += 1
    state["question"] = llm_rewrite(state["question"])

def decide_next(state: State):
    if state["retries"] >= 3:
        return "generate"
    return "rewrite_query" if poor(state) else "generate"

